{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would require each school district and public charter school to set aside one instructional day each school year to observe the Fourth of July through age-appropriate instruction for students in kindergarten through grade 12. The instruction would cover the founding of the United States, the original colonies’ separation from Great Britain, the Declaration of Independence, the Constitution, and fundamental rights and freedoms.",
      "rationale": "Conveys the annual instructional day, covered schools and students, and required subjects. The summary also identifies directors as responsible for designation and requires grade-specific goals."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Schools could choose their instructional programs and methods, but the lessons would have to meet grade-specific goals.",
      "rationale": "Conveys local selection of programs and methods subject to mandatory grade-specific objectives. The bill's illustrative methods are optional examples."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Students in kindergarten through grade 5 would learn basic ideas of independence, freedom, rights, and national symbols.",
      "rationale": "Covers the grade range and general subjects but omits explaining the Fourth of July's meaning, identifying the United States as independent, and connecting national symbols to freedom and independence."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "Students in grades 6 through 8 would study the events and reasons behind independence, the founding documents, and civic principles.",
      "rationale": "Covers the grade range and broad subjects but omits the specific required competencies, the enumerated civic principles, and the option to accomplish these objectives through social studies."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "Students in grades 9 through 12 would analyze the founding documents and themes of the American Revolution and connect founding principles to citizenship today.",
      "rationale": "Covers document analysis, revolutionary themes, and modern citizenship connections, but omits evaluating independence's historical and philosophical significance, the specified themes, and the English language arts curriculum option."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "School district and charter school directors would have to designate the day annually, ensure the instruction is carried out, verify that it meets the bill’s requirements, and provide guidance as needed.",
      "rationale": "Identifies the responsible directors and their implementation and guidance duties, but does not convey the requirement for consistent implementation at each school."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "School district and charter school directors would have to designate the day annually, ensure the instruction is carried out, verify that it meets the bill’s requirements, and provide guidance as needed. Instruction given in a social studies or English language arts class would also have to align with relevant state academic standards.",
      "rationale": "Conveys directors' compliance-verification responsibility and the conditional standards-alignment requirement for social studies and English language arts instruction."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "All instruction would have to be nonpartisan and solely educational.",
      "rationale": "Conveys the nonpartisan and educational requirements but omits the independent requirement to focus at all times on historical facts, founding-document content, and underlying civic principles."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "Districts and charter schools would periodically review their materials and methods and update them as they consider appropriate.",
      "rationale": "Conveys periodic review and discretionary updating, but omits review of content and the purposes of implementing civic-education best practices and ensuring conditional standards alignment."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law and apply beginning with the 2026–2027 school year.",
      "rationale": "Conveys immediate effectiveness upon becoming law and ongoing application beginning in the specified school year."
    }
  ]
}
